// VFF service worker — what lets the app OPEN with no signal.
//
// Before this, the app degraded offline but couldn't start offline: every
// tick was safe in localStorage, but a hard reload in a hangar fetched the page
// itself from the network and got nothing, so the member was looking at a blank
// screen with their work intact underneath it. This worker keeps a copy of the
// pages a flying day needs, the code they run, and the last answer to each API
// read, and hands those back when the network can't.
//
// Hand-written rather than generated by Workbox/Serwist, for the same reason
// the app hand-writes its xlsx and ics: the rules fit on one screen, and a
// build plugin would be more machinery than policy. It is a CLASSIC script (not
// a module worker) because older iOS Safari can't run a module worker.
//
// Five kinds of request, five rules (see `classify`):
//
//   static  /_next/static/*  — CACHE FIRST. Every file there has a content
//           hash in its name, so a cached copy can never be the wrong one.
//   page    a navigation     — NETWORK FIRST, with a short deadline, then the
//           cached copy of that page, then a small "not saved yet" page. A
//           slow ramp connection gets the saved page after NAV_TIMEOUT_MS
//           instead of a spinner, and the real one still lands in the cache.
//   api     GET /api/*       — NETWORK FIRST, then the last answer, which is
//           marked with the `x-vff-cached-at` header so the app can say "this
//           is what this device last saw, at 7:40" (lib/api.ts). If there's no
//           saved answer the page gets the real network failure, exactly as
//           before — a cache must never invent an empty list.
//   asset   icons, manifest  — stale-while-revalidate.
//   (none)  everything else, and every non-GET — straight to the network.
//           WRITES ARE NEVER CACHED OR REPLAYED HERE: that's the outbox's job
//           (lib/outbox.ts), which can freeze a submission, key it, and tell
//           the member about it. A worker silently replaying POSTs can do none
//           of that.
//
// Two exclusions worth their sentence. Next's RSC requests (client-side
// navigations) are left alone: their payloads depend on router state headers,
// and serving a mismatched one breaks the page. When one fails offline, Next
// falls back to a full navigation — which this worker then answers from the
// page cache. And /api/photos is left alone: photos are large, and caching
// every one ever viewed would fill the device for a feature nobody needs
// offline.
//
// API answers belong to whoever was signed in, so the page empties that cache
// on sign-out and whenever the member changes (lib/serviceWorker.ts).
//
// Versioning: the page registers `/sw.js?v=<commit sha>`. A new sha is a new
// worker, and its `activate` drops every cache from older builds.

const VERSION = new URL(self.location.href).searchParams.get("v") || "0";
const STATIC_CACHE = "vff-static-" + VERSION;
const PAGE_CACHE = "vff-pages-" + VERSION;
const API_CACHE = "vff-api-" + VERSION;
const META_CACHE = "vff-meta";

/** The pages a flying day goes through, fetched ahead while there's signal. */
const SHELL_ROUTES = [
  "/status",
  "/preflight",
  "/runway",
  "/postflight",
  "/quick-log",
  "/log",
  "/reservations",
  "/servicing",
  "/status/squawks",
  "/status/maintenance",
  "/tools/weight-balance",
  "/tools/my-plane",
];

const NAV_TIMEOUT_MS = 4000;
const API_TIMEOUT_MS = 8000;
/** How stale the warm copies may get before a load refreshes them. */
const WARM_EVERY_MS = 6 * 60 * 60 * 1000;

/**
 * The most API answers kept. The cache is keyed by full URL, and some reads
 * carry the current time in their query (the reservations window), so without
 * a cap every load would add an entry nobody will ever match again and the
 * cache would climb for the life of the build.
 */
const API_CACHE_MAX_ENTRIES = 150;

const CACHED_AT_HEADER = "x-vff-cached-at";
const FETCHED_AT_HEADER = "x-vff-fetched-at";

/**
 * Which rule a request falls under, or null to leave it to the network.
 * Pure, and unit-tested (tests/unit/serviceWorker.test.ts).
 */
function classify(url, method, mode, headers, origin) {
  if (method !== "GET") return null;
  if (url.origin !== origin) return null;
  const path = url.pathname;
  if (path.startsWith("/_next/static/")) return "static";
  // Client-side navigations. See the header comment.
  if (headers.get("RSC") === "1" || url.searchParams.has("_rsc")) return null;
  if (path === "/sw.js") return null;
  // API first, so a NAVIGATION to one — the OAuth callback, an export link —
  // is never mistaken for a page and answered from the page cache.
  if (path.startsWith("/api/")) {
    if (mode === "navigate") return null;
    if (path === "/api/auth/session") return "api";
    if (path.startsWith("/api/auth/") || path.startsWith("/api/photos/")) return null;
    return "api";
  }
  if (mode === "navigate") return "page";
  if (
    path.startsWith("/icons/") ||
    path === "/icon.svg" ||
    path === "/apple-icon.png" ||
    path === "/manifest.webmanifest"
  ) {
    return "asset";
  }
  return null;
}

/** The pathname, as the key a page is cached under (no query, no hash). */
function pageKey(url) {
  return new URL(url).origin + new URL(url).pathname;
}

const TIMED_OUT = Symbol("timed out");
const FAILED = Symbol("failed");

/** The promise's value, or TIMED_OUT after `ms`, or FAILED if it rejects. */
function within(promise, ms) {
  return new Promise((resolve) => {
    const timer = setTimeout(() => resolve(TIMED_OUT), ms);
    promise.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      () => {
        clearTimeout(timer);
        resolve(FAILED);
      }
    );
  });
}

/** A copy of `res` stamped with when it was fetched, for the cache. */
async function stamped(res) {
  const headers = new Headers(res.headers);
  headers.set(FETCHED_AT_HEADER, new Date().toISOString());
  return new Response(await res.blob(), {
    status: res.status,
    statusText: res.statusText,
    headers,
  });
}

/** A cached copy, re-labelled so the page knows it isn't live. */
function asCached(res) {
  const headers = new Headers(res.headers);
  headers.set(CACHED_AT_HEADER, res.headers.get(FETCHED_AT_HEADER) || "");
  headers.delete(FETCHED_AT_HEADER);
  return new Response(res.body, { status: res.status, statusText: res.statusText, headers });
}

/**
 * Drop the oldest entries past `max`. `keys()` comes back in insertion order,
 * and `put` on an existing key re-inserts it at the end, so "oldest" here is
 * "least recently refreshed" — the ones a member hasn't opened in longest.
 */
async function trim(cache, max) {
  const keys = await cache.keys();
  const excess = keys.length - max;
  for (let i = 0; i < excess; i++) await cache.delete(keys[i]);
}

/** Whether a response is an HTML document — the only kind cached as a page. */
function isHtml(res) {
  return (res.headers.get("content-type") || "").includes("text/html");
}

/** Static rule: the cached copy if there is one, otherwise fetch and keep it. */
async function cacheFirst(request) {
  const cache = await caches.open(STATIC_CACHE);
  const hit = await cache.match(request);
  if (hit) return hit;
  const res = await fetch(request);
  if (res.ok) await cache.put(request, res.clone());
  return res;
}

/** Asset rule: answer from the cache at once, refresh it in the background. */
async function staleWhileRevalidate(event) {
  const cache = await caches.open(STATIC_CACHE);
  const hit = await cache.match(event.request);
  const refresh = fetch(event.request).then((res) => {
    if (res.ok) return cache.put(event.request, res.clone()).then(() => res);
    return res;
  });
  event.waitUntil(refresh.catch(() => {}));
  return hit || refresh;
}

/** Page rule — see the header comment. */
async function networkFirstPage(event) {
  const request = event.request;
  const key = pageKey(request.url);
  const network = fetch(request).then(async (res) => {
    // Only a real page lands in the cache. A redirect (to /login, for a
    // member whose session lapsed) is NOT the page that was asked for, and
    // caching it under this path would show the login screen offline.
    if (res.ok && !res.redirected && isHtml(res)) {
      const cache = await caches.open(PAGE_CACHE);
      await cache.put(key, res.clone());
    }
    return res;
  });
  event.waitUntil(network.catch(() => {}));

  const first = await within(network, NAV_TIMEOUT_MS);
  if (first instanceof Response) return first;

  const cached = await (await caches.open(PAGE_CACHE)).match(key);
  if (cached) return cached;
  // Slow rather than gone: no saved copy to offer, so wait for the real one.
  if (first === TIMED_OUT) {
    const late = await within(network, 60000);
    if (late instanceof Response) return late;
  }
  return offlinePage();
}

/** API rule — see the header comment. */
async function networkFirstApi(event) {
  const request = event.request;
  const network = fetch(request).then(async (res) => {
    if (res.status === 200) {
      const cache = await caches.open(API_CACHE);
      await cache.put(request, await stamped(res.clone()));
      await trim(cache, API_CACHE_MAX_ENTRIES);
    }
    return res;
  });
  event.waitUntil(network.catch(() => {}));

  const first = await within(network, API_TIMEOUT_MS);
  if (first instanceof Response) return first;

  const cached = await (await caches.open(API_CACHE)).match(request);
  if (cached) return asCached(cached);
  // Nothing saved: the page gets whatever the network eventually does,
  // failure included — never an invented answer.
  return network;
}

/** The small page shown for a route this device has never saved. */
function offlinePage() {
  const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>No signal — VFF</title>
<style>
  :root { color-scheme: light dark; font-family: system-ui, -apple-system, sans-serif; }
  body { margin: 0; min-height: 100vh; display: grid; place-items: center; background: #f9fafb; color: #111827; padding: 1.5rem; box-sizing: border-box; }
  main { max-width: 26rem; }
  h1 { font-size: 1.25rem; margin: 0 0 .5rem; }
  p { line-height: 1.5; color: #4b5563; margin: 0 0 1rem; }
  a, button { display: inline-block; font: inherit; font-weight: 600; padding: .5rem 1rem; border-radius: .5rem; margin: 0 .5rem .5rem 0; text-decoration: none; }
  button { background: #ea580c; color: #fff; border: 0; }
  a { color: #ea580c; border: 1px solid #fdba74; }
  @media (prefers-color-scheme: dark) {
    body { background: #111827; color: #f9fafb; }
    p { color: #9ca3af; }
  }
</style></head>
<body><main>
  <h1>No signal, and this page isn't saved on this device yet.</h1>
  <p>Anything you've ticked on a checkout or filed while offline is safe on this device and will be sent when you're back in range.</p>
  <button onclick="location.reload()">Try again</button>
  <a href="/preflight">Preflight</a><a href="/postflight">Post-flight</a><a href="/quick-log">Quick Log</a>
</main></body></html>`;
  return new Response(html, {
    status: 503,
    headers: { "content-type": "text/html; charset=utf-8" },
  });
}

/**
 * Fetch the flying-day pages, and every hashed file they reference, into the
 * cache — at most once per WARM_EVERY_MS per build. Sequential on purpose: it
 * runs while a member is using the app, on a connection that may be the
 * clubhouse wifi, and it must never compete with what they're doing.
 */
async function warm() {
  const meta = await caches.open(META_CACHE);
  const stampKey = "/__warmed__";
  const last = await meta.match(stampKey);
  if (last) {
    const { version, at } = await last.json();
    if (version === VERSION && Date.now() - at < WARM_EVERY_MS) return;
  }

  const pages = await caches.open(PAGE_CACHE);
  const statics = await caches.open(STATIC_CACHE);
  let warmedAny = false;
  for (const route of SHELL_ROUTES) {
    let res;
    try {
      res = await fetch(route, { credentials: "same-origin" });
    } catch {
      return; // signal went; try again next load
    }
    if (!res.ok || res.redirected || !isHtml(res)) continue;
    const html = await res.clone().text();
    await pages.put(pageKey(new URL(route, self.location.origin).href), res);
    warmedAny = true;

    const assets = new Set(html.match(/\/_next\/static\/[^"'\s)\\]+/g) || []);
    for (const asset of assets) {
      if (await statics.match(asset)) continue;
      try {
        const a = await fetch(asset);
        if (a.ok) await statics.put(asset, a);
      } catch {
        return;
      }
    }
  }
  // Only stamp a warm that actually saved something. A member who wasn't
  // signed in gets redirected on every route, and stamping that would put off
  // the real warm for six hours.
  if (warmedAny) {
    await meta.put(
      stampKey,
      new Response(JSON.stringify({ version: VERSION, at: Date.now() }), {
        headers: { "content-type": "application/json" },
      })
    );
  }
}

self.addEventListener("install", () => {
  // Take over as soon as installed: a member mid-flight shouldn't have to
  // close every tab before the new build's pages can be saved.
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const current = [STATIC_CACHE, PAGE_CACHE, API_CACHE, META_CACHE];
      const names = await caches.keys();
      await Promise.all(
        names
          .filter((n) => n.startsWith("vff-") && !current.includes(n))
          .map((n) => caches.delete(n))
      );
      await self.clients.claim();
    })()
  );
});

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "warm") {
    event.waitUntil(warm().catch(() => {}));
  }
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  const kind = classify(
    new URL(request.url),
    request.method,
    request.mode,
    request.headers,
    self.location.origin
  );
  if (kind === "static") event.respondWith(cacheFirst(request));
  else if (kind === "page") event.respondWith(networkFirstPage(event));
  else if (kind === "api") event.respondWith(networkFirstApi(event));
  else if (kind === "asset") event.respondWith(staleWhileRevalidate(event));
});
